// config.js — 흩어져 있으면 무엇이 필요한지 아무도 모른다
export const config = {
  apiUrl: process.env.API_URL ?? 'http://localhost:3000',
  token: required('API_TOKEN'),
};

function required(name) {
  const v = process.env[name];
  if (!v) throw new Error(`환경변수 ${name} 이 없습니다`);   // 조용히 undefined 로 도는 것보다 낫다
  return v;
}
